patch -p0 <<'PATCH'
--- tests/src/unit-udt.cpp
+++ tests/src/unit-udt.cpp
@@ -19,9 +19,12 @@
     using namespace nlohmann::literals; // NOLINT(google-build-using-namespace)
 #endif

+#include <cstdint>
+#include <limits>
 #include <map>
 #include <memory>
 #include <string>
+#include <type_traits>
 #include <utility>

 namespace udt
@@ -224,6 +227,49 @@
 }
 } // namespace udt

+TEST_CASE_TEMPLATE("enum serialization preserves underlying signedness" * doctest::test_suite("udt"), T,
+                   std::int8_t, std::uint8_t, std::int16_t, std::uint16_t,
+                   std::int32_t, std::uint32_t, std::int64_t, std::uint64_t)
+{
+    enum class scoped_enum : T {};
+    enum unscoped_enum : T {};
+
+    for (const auto value : {(std::numeric_limits<T>::min)(), T(0), T(1), (std::numeric_limits<T>::max)()})
+    {
+        const auto scoped = static_cast<scoped_enum>(value);
+        const auto unscoped = static_cast<unscoped_enum>(value);
+
+        for (const json& j : {json(scoped), json(unscoped)})
+        {
+            CHECK(j.type() == (std::is_unsigned<T>::value ? json::value_t::number_unsigned : json::value_t::number_integer));
+            CHECK(j == value);
+            CHECK(to_string(j) == std::to_string(value));
+            CHECK(j.get<scoped_enum>() == scoped);
+            CHECK(j.get<unscoped_enum>() == unscoped);
+        }
+    }
+}
+
+TEST_CASE("large unsigned enum serialization" * doctest::test_suite("udt"))
+{
+    enum class book_id : std::uint64_t {};
+    const auto large_id = static_cast<book_id>(std::uint64_t(1) << 63);
+    const json j = large_id;
+
+    CHECK(j > 0u);
+    CHECK(to_string(j) == "9223372036854775808");
+    CHECK(j.is_number_unsigned());
+
+    const auto special_id = static_cast<book_id>((std::numeric_limits<std::uint64_t>::max)() - 1);
+    CHECK(to_string(json(special_id)) == "18446744073709551614");
+}
+
 TEST_CASE("basic usage" * doctest::test_suite("udt"))
 {

